begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where is_active and role='super_admin' order by id limit 1),true);
set local role authenticated;
do $test$
declare a uuid; b uuid; ia uuid; ib uuid; ic uuid; pay uuid; other_pay uuid; cr uuid; manual uuid; ref uuid; app uuid; req uuid; method uuid; stamp timestamptz; doc jsonb; cmd jsonb; failed boolean; value numeric;
begin
 insert into public.clients(name) values('QA Finance A') returning id into a;
 insert into public.clients(name) values('QA Finance B') returning id into b;
 insert into public.payment_methods(name) values('QA Original Method') returning id into method;
 doc:=jsonb_build_object('kind','invoice','document_kind','quote','client_id',a,'client_name','QA Finance A','client_email',null,'seller_name','QA Seller','billing_address','Billing snapshot','shipping_address','Shipping snapshot','payment_terms','days','payment_terms_days',30,'payment_method_id',null,'payment_method_name',null,'tax_exempt',false,'issue_date','2026-10-26','valid_until','2026-11-26','purchase_order',null,'project_description',null,'public_notes','Public','private_notes','Private','footer_notes','Footer','discount_mode','none','discount_value',0,'shipping_amount',0,'shipping_tax_rate',0,'items',jsonb_build_array(jsonb_build_object('item_id',null,'description','QA Service','quantity',1,'unit_price',100,'tax_rate',0,'discount_percent',0)));
 ia:=public.save_commercial_document(doc,null,null,gen_random_uuid(),null,false);
 ib:=public.save_commercial_document(doc,null,null,gen_random_uuid(),null,false);
 ic:=public.save_commercial_document(doc||jsonb_build_object('client_id',b,'client_name','QA Finance B'),null,null,gen_random_uuid(),null,false);
 cmd:=jsonb_build_object('operation','payment.create','client_id',a,'amount',150,'date','2026-10-26','payment_method_id',null,'reference','QA-150','notes','QA note','allocations',jsonb_build_array(jsonb_build_object('invoice_id',ia,'amount',100),jsonb_build_object('invoice_id',ib,'amount',30)));
 cmd:=cmd||jsonb_build_object('payment_method_id',method);
 req:=gen_random_uuid(); pay:=public.bbs_finance_command(cmd,req);
 update public.payment_methods set name='QA Renamed Method' where id=method;
 if not exists(select 1 from public.payments where id=pay and payment_method_name='QA Original Method') then raise exception 'Payment method snapshot changed with catalog'; end if;
 if public.bbs_finance_command(cmd,req)<>pay then raise exception 'Payment idempotency failed'; end if;
 if not exists(select 1 from public.invoices where id=ia and amount_paid=100 and amount_credited=0 and status='paid') or not exists(select 1 from public.invoices where id=ib and amount_paid=30 and status='partial') then raise exception 'Payment allocation balances failed'; end if;
 select p.amount-coalesce((select sum(amount) from public.finance_applications where source_id=p.id and source_kind='payment' and reversed_at is null),0) into value from public.payments p where id=pay;
 if value<>20 then raise exception 'Overpayment remainder failed'; end if;
 failed:=false; begin perform public.bbs_finance_command(cmd||'{"amount":151}',req); exception when raise_exception then failed:=sqlerrm like '%Solicitud reutilizada%'; end; if not failed then raise exception 'Mismatched retry accepted'; end if;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','application.apply','source_kind','payment','source_id',pay,'allocations',jsonb_build_array(jsonb_build_object('invoice_id',ib,'amount',21))),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Payment over-application accepted'; end if;
 perform public.bbs_finance_command(jsonb_build_object('operation','application.apply','source_kind','payment','source_id',pay,'allocations',jsonb_build_array(jsonb_build_object('invoice_id',ib,'amount',20))),gen_random_uuid());
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','application.apply','source_kind','payment','source_id',pay,'allocations',jsonb_build_array(jsonb_build_object('invoice_id',ic,'amount',1))),gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%cliente%'; end; if not failed then raise exception 'Cross-client application accepted'; end if;
 select id into app from public.finance_applications where source_kind='payment' and source_id=pay and invoice_id=ib and amount=30 and reversed_at is null;
 perform public.bbs_finance_command(jsonb_build_object('operation','application.unapply','application_id',app,'reason','QA Undo'),gen_random_uuid());
 if not exists(select 1 from public.invoices where id=ib and amount_paid=20) then raise exception 'Payment undo did not restore balance'; end if;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','payment.void','id',pay,'reason','QA invalid void'),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Applied payment void accepted'; end if;
 select updated_at into stamp from public.payments where id=pay;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','payment.update','id',pay,'version',stamp-interval '1 second','date','2026-10-26','payment_method_id',null,'reference','STALE','notes',null),gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%Otro usuario%'; end; if not failed then raise exception 'Stale payment edit accepted'; end if;
 perform public.bbs_finance_command(jsonb_build_object('operation','payment.update','id',pay,'version',stamp,'date','2026-10-26','payment_method_id',null,'reference','UPDATED','notes','Updated note'),gen_random_uuid());
 manual:=public.bbs_finance_command(jsonb_build_object('operation','credit.create','document',jsonb_set(doc,'{items,0,unit_price}','40'),'source_invoice_id',null,'reason','QA manual credit','allocations',jsonb_build_array(jsonb_build_object('invoice_id',ib,'amount',20))),gen_random_uuid());
 if not exists(select 1 from public.invoices where id=ib and amount_paid=20 and amount_credited=20) then raise exception 'Credit counted as cash or missing'; end if;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','credit.void','id',manual,'reason','QA invalid void'),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Applied credit void accepted'; end if;
 select id into app from public.finance_applications where source_kind='credit' and source_id=manual and reversed_at is null;
 perform public.bbs_finance_command(jsonb_build_object('operation','application.unapply','application_id',app,'reason','QA Undo credit'),gen_random_uuid());
 select updated_at into stamp from public.credit_notes where id=manual;
 perform public.bbs_finance_command(jsonb_build_object('operation','credit.update','id',manual,'version',stamp,'document',jsonb_set(doc,'{items,0,unit_price}','30'),'reason','QA edit unused credit'),gen_random_uuid());
 if not exists(select 1 from public.credit_notes where id=manual and total=30) then raise exception 'Unused credit edit failed'; end if;
 cr:=public.bbs_finance_command(jsonb_build_object('operation','credit.create','document',jsonb_set(doc,'{items,0,unit_price}','50'),'source_invoice_id',ia,'reason','QA paid invoice return','allocations','[]'::jsonb),gen_random_uuid());
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','credit.create','document',jsonb_set(doc,'{items,0,unit_price}','51'),'source_invoice_id',ia,'reason','QA excessive credit','allocations','[]'::jsonb),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Credits exceeded invoice total'; end if;
 other_pay:=public.bbs_finance_command(jsonb_build_object('operation','payment.create','client_id',a,'amount',10,'date','2026-10-26','payment_method_id',null,'reference',null,'notes',null,'allocations','[]'::jsonb),gen_random_uuid());
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',a,'payment_id',other_pay,'credit_note_id',cr,'amount',1,'date','2026-10-26','payment_method_id',null,'reference',null,'reason','QA wrong backing payment'),gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%no respalda%'; end; if not failed then raise exception 'Invoice credit refund accepted unrelated payment'; end if;
 ref:=public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',a,'payment_id',other_pay,'credit_note_id',null,'amount',2,'date','2026-10-26','payment_method_id',null,'reference',null,'reason','QA excess deposit refund'),gen_random_uuid());
 perform public.bbs_finance_command(jsonb_build_object('operation','refund.void','id',ref,'reason','QA deposit refund reversed'),gen_random_uuid());
 perform public.bbs_finance_command(jsonb_build_object('operation','payment.void','id',other_pay,'reason','QA unused deposit void'),gen_random_uuid());
 ref:=public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',a,'payment_id',pay,'credit_note_id',cr,'amount',40,'date','2026-10-26','payment_method_id',method,'reference','QA RETURN','reason','QA paid refund'),gen_random_uuid());
 update public.payment_methods set name='QA Later Method' where id=method;
 if not exists(select 1 from public.refunds where id=ref and payment_method_name='QA Renamed Method') then raise exception 'Refund method snapshot changed with catalog'; end if;
 if not exists(select 1 from public.invoices where id=ia and amount_paid=60 and amount_credited=40 and status='paid') then raise exception 'Paid invoice refund reopened debt'; end if;
 select credit_application_id into app from public.refunds where id=ref;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','application.unapply','application_id',app,'reason','QA invalid undo'),gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%reembolso%'; end; if not failed then raise exception 'Refund credit application was independently undone'; end if;
 perform public.bbs_finance_command(jsonb_build_object('operation','refund.void','id',ref,'reason','QA refund reversed'),gen_random_uuid());
 if not exists(select 1 from public.invoices where id=ia and amount_paid=100 and amount_credited=0 and status='paid') then raise exception 'Paid refund void failed'; end if;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',b,'payment_id',pay,'credit_note_id',null,'amount',1,'date','2026-10-26','payment_method_id',null,'reference',null,'reason','QA other client'),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Cross-client refund accepted'; end if;
 failed:=false; begin perform public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',a,'payment_id',pay,'credit_note_id',null,'amount',31,'date','2026-10-26','payment_method_id',null,'reference',null,'reason','QA excess'),gen_random_uuid()); exception when raise_exception then failed:=true; end; if not failed then raise exception 'Excess cash refund accepted'; end if;
 ref:=public.bbs_finance_command(jsonb_build_object('operation','refund.create','client_id',a,'payment_id',pay,'credit_note_id',manual,'amount',25,'date','2026-10-26','payment_method_id',null,'reference','QA manual refund','reason','QA refund'),gen_random_uuid());
 perform public.bbs_finance_command(jsonb_build_object('operation','refund.void','id',ref,'reason','QA manual refund undone'),gen_random_uuid());
 perform public.bbs_finance_command(jsonb_build_object('operation','credit.void','id',manual,'reason','QA unused credit void'),gen_random_uuid());
 for app in select id from public.finance_applications where source_kind='payment' and source_id=pay and reversed_at is null loop perform public.bbs_finance_command(jsonb_build_object('operation','application.unapply','application_id',app,'reason','QA Undo all cash'),gen_random_uuid()); end loop;
 perform public.bbs_finance_command(jsonb_build_object('operation','payment.void','id',pay,'reason','QA unused payment void'),gen_random_uuid());
 if not exists(select 1 from public.payments where id=pay and voided_at is not null) then raise exception 'Unused payment void failed'; end if;
 failed:=false; begin update public.invoices set amount_paid=99 where id=ia; exception when raise_exception then failed:=true; end; if not failed then raise exception 'Direct balance change accepted'; end if;
 failed:=false; begin insert into public.payments(client_id,amount) values(a,1); exception when insufficient_privilege then failed:=true; end; if not failed then raise exception 'Direct cash insert accepted'; end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 failed:=false; begin perform public.bbs_finance_command(cmd,gen_random_uuid()); exception when insufficient_privilege then failed:=true; end; if not failed then raise exception 'Non-admin finance command accepted'; end if;
end $test$;
rollback;
